package com.srctool.camouflage.core.theme

import androidx.compose.runtime.Immutable
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.lerp
import androidx.compose.ui.unit.Dp

/**
 * A brand's own typed tokens (ADR-32), usually generated by `camo theme import`.
 * Read with [CamoTheme.tokens]; [lerp] lets animated theme switches blend it.
 */
public interface CamoTokenSet<T : CamoTokenSet<T>> {
    public fun lerp(to: T, fraction: Float): T
}

internal const val MIDPOINT: Float = 0.5f

/** A numbered color scale, as brands name them (`brand[600]`). */
@Immutable
public class CamoColorScale(private val steps: Map<Int, Color>) {
    public operator fun get(step: Int): Color = steps[step] ?: error("No step $step in this scale")

    /** Blends the steps both scales have; a step only one scale has switches at the midpoint. */
    public fun lerp(to: CamoColorScale, t: Float): CamoColorScale = CamoColorScale(
        (steps.keys + to.steps.keys).associateWith { step ->
            val a = steps[step]
            val b = to.steps[step]
            when {
                a != null && b != null -> lerp(a, b, t)
                else -> if (t < MIDPOINT) a ?: b!! else b ?: a!!
            }
        },
    )

    override fun equals(other: Any?): Boolean = other is CamoColorScale && other.steps == steps
    override fun hashCode(): Int = steps.hashCode()
}

/** A named dimension scale (`space["lg"]`). */
@Immutable
public class CamoDimensionScale(private val steps: Map<String, Dp>) {
    public operator fun get(name: String): Dp = steps[name] ?: error("No step \"$name\" in this scale")

    override fun equals(other: Any?): Boolean = other is CamoDimensionScale && other.steps == steps
    override fun hashCode(): Int = steps.hashCode()
}
